value.data:
kind: TaskDialog
response:
  activity:
    attachments:
      - kind: AdaptiveCardTemplate
        cardContent: |
          ={
            type: "AdaptiveCard",
            '$schema': "http://adaptivecards.io/schemas/adaptive-card.json",
            version: "1.6",
            body: [
              {
                type: "TextBlock",
                text: "Agent Evaluation Summary",
                weight: "Bolder",
                size: "Large",
                wrap: true
              },
              {
                type: "TextBlock",
                text: "Overall Score",
                spacing: "Small",
                isSubtle: true
              },
              {
                type: "Chart.Gauge",
                title: "Overall Score",
                value: ParseJSON(Topic.Output.review_result).overall_score,
                valueFormat: "Number",
                colorSet: "categorical",
                segments: [
                  {
                    legend: "Score",
                    size: 100,
                    color: "good"
                  }
                ]
              },
              {
                type: "FactSet",
                facts: [
                  { title: "Agent Name:", value: Text(ParseJSON(Topic.Output.review_result).BotName) },
                  { title: "Bot ID:", value: Text(ParseJSON(Topic.Output.review_result).BotId) },
                  { title: "Type:", value: If(ParseJSON(Topic.Output.review_result).IsGenerativeOrchestration, "Generative Orchestration", "Classic") },
                  { title: "Score:", value: Text(ParseJSON(Topic.Output.review_result).overall_score) & " / 100" },
                  { title: "Topics analyzed:", value: Text(ParseJSON(Topic.Output.review_result).Summary.topics_analyzed) },
                  { title: "Failed components:", value: Text(ParseJSON(Topic.Output.review_result).Summary.failed_components) }
                ],
                spacing: "Medium"
              },
              {
                type: "TextBlock",
                text: "Review Summary",
                weight: "Bolder",
                spacing: "Medium"
              },
              {
                type: "TextBlock",
                text: "The agent scored " & Text(ParseJSON(Topic.Output.review_result).overall_score) & "/100. Expand patterns below for findings and recommendations.",
                wrap: true
              },
              {
                type: "TextBlock",
                text: "Patterns",
                weight: "Bolder",
                spacing: "Medium"
              },
              {
                type: "Container",
                items: ForAll(
                  FirstN(ParseJSON(Topic.Output.review_result).Patterns, 25),
                  {
                    type: "Container",
                    spacing: "Small",
                    separator: true,
                    items: [
                      {
                        type: "ColumnSet",
                        columns: [
                          {
                            type: "Column",
                            width: "stretch",
                            items: [
                              {
                                type: "TextBlock",
                                text: If(IsBlank(ThisRecord.title), ThisRecord.pattern, ThisRecord.title),
                                weight: "Bolder",
                                wrap: true
                              },
                              {
                                type: "TextBlock",
                                text: If(!IsBlank(ThisRecord.description), ThisRecord.description),
                                isSubtle: true,
                                wrap: true,
                                spacing: "None"
                              }
                            ]
                          },
                          {
                            type: "Column",
                            width: "auto",
                            verticalContentAlignment: "Center",
                            items: [
                              {
                                type: "Container",
                                minWidth: "80px",
                                maxWidth: "100px",
                                items: [
                                  {
                                    type: "Badge",
                                    text: If(
                                      !IsBlank(ThisRecord.topics) && CountRows(ThisRecord.topics) > 0,
                                      "Fail",
                                      If(
                                        ParseJSON(Topic.Output.review_result).IsGenerativeOrchestration &&
                                        (
                                          CountRows(Filter(Table(ThisRecord.topics), Value.quality_score = "too_short" || Value.quality_score = "unclear")) > 0 ||
                                          CountRows(Filter(Table(ThisRecord.topics), !IsBlank(Value.missing_fields))) > 0
                                        ),
                                        "Warning",
                                        "Pass"
                                      )
                                    ),
                                    size: "Large",
                                    style: If(
                                      !IsBlank(ThisRecord.topics) && CountRows(ThisRecord.topics) > 0,
                                      "Attention",
                                      "Good"
                                    )
                                  }
                                ]
                              }
                            ]
                          },
                          {
                            type: "Column",
                            width: "auto",
                            verticalContentAlignment: "Center",
                            items: [
                              {
                                type: "Image",
                                id: "icon_down_" & Substitute(ThisRecord.pattern, " ", "_"),
                                url: "https://adaptivecards.io/content/down.png",
                                altText: "Expand",
                                width: "18px",
                                selectAction: {
                                  type: "Action.ToggleVisibility",
                                  targetElements: [
                                    "detail_" & Substitute(ThisRecord.pattern, " ", "_"),
                                    "icon_down_" & Substitute(ThisRecord.pattern, " ", "_"),
                                    "icon_up_" & Substitute(ThisRecord.pattern, " ", "_")
                                  ]
                                }
                              },
                              {
                                type: "Image",
                                id: "icon_up_" & Substitute(ThisRecord.pattern, " ", "_"),
                                url: "https://adaptivecards.io/content/up.png",
                                altText: "Collapse",
                                width: "18px",
                                isVisible: false,
                                selectAction: {
                                  type: "Action.ToggleVisibility",
                                  targetElements: [
                                    "detail_" & Substitute(ThisRecord.pattern, " ", "_"),
                                    "icon_down_" & Substitute(ThisRecord.pattern, " ", "_"),
                                    "icon_up_" & Substitute(ThisRecord.pattern, " ", "_")
                                  ]
                                }
                              }
                            ]
                          }
                        ]
                      },
                      {
                        type: "Container",
                        id: "detail_" & Substitute(ThisRecord.pattern, " ", "_"),
                        isVisible: false,
                        spacing: "Small",
                        items: [
                          {
                            type: "TextBlock",
                            text: "Topics affected:",
                            weight: "Bolder",
                            spacing: "Small"
                          },
                          {
                            type: "Container",
                            items: If(
                              IsBlank(ThisRecord.topics),
                              [{ type: "TextBlock", text: "No Topics affected", isSubtle: true }],
                              ForAll(
                                ThisRecord.topics,
                                {
                                  type: "Container",
                                  spacing: "Small",
                                  items: [
                                    { type: "TextBlock", text: "• Topic Name: " & ThisRecord.topic_name, weight: "Bolder", wrap: true },
                                    { type: "TextBlock", text: "  Recommendation: " & ThisRecord.recommendation, isSubtle: true, wrap: true },
                                    {
                                      type: "TextBlock",
                                      text: "  Sample triggers: " & Concat(Table(ThisRecord.sample_triggers),Value.items),
                                      isSubtle: true,
                                      wrap: true
                                    }
                                  ]
                                }
                              )
                            )
                          }
                        ]
                      }
                    ]
                  }
                )
              },
              {
                type: "TextBlock",
                text: "Recommendations (Summary)",
                weight: "Bolder",
                spacing: "Medium"
              },
              {
                type: "Container",
                items: If(
                  CountRows(ParseJSON(Topic.Output.review_result).Patterns) = 0,
                  [{ type: "TextBlock", text: "No recommendations available.", isSubtle: true }],
                  [
                    {
                      type: "TextBlock",
                      text: Concat(
                        Filter(
                          Table(ParseJSON(Topic.Output.review_result).Patterns),
                          !IsBlank(Value.topics) && CountRows(Value.topics) > 0
                        ),
                        Concat(
                          Table(Value.topics),
                          If(
                            !IsBlank(Value.recommendation),
                            Value.topic_name & ": " & Value.recommendation & Char(10),
                            ""
                          )
                        )
                      ),
                      wrap: true
                    }
                  ]
                )
              }
            ],
            actions: [
              {
                type: "Action.OpenUrl",
                title: "Download PDF",
                url: Topic.Output.file_url,
                iconUrl: "icon:ArrowDownload"
              }
            ],
            fallbackText:
              "Agent Evaluation summary: " &
              ParseJSON(Topic.Output.review_result).BotName &
              " - Score: " &
              Text(ParseJSON(Topic.Output.review_result).overall_score)
          }

  mode: Strict

inputs:
  - kind: ManualTaskInput
    propertyName: text
    value: =Global.varBotID

modelDisplayName: Evaluate Copilot Studio Agent
modelDescription: A tool to review an agent aka bot whenever its id is provided
outputs:
  - propertyName: review_result

action:
  kind: InvokeFlowTaskAction
  flowId: 3b131928-8094-f011-b41c-6045bdef4136

outputMode: All
triggerCondition: false
